		"$:/plugins/euth/drawers/stylesheet": {
			"text": "\rules only filteredtranscludeinline transcludeinline macrodef macrocallinline html

/* BOTH DRAWERS */

.tc-page-container-inner>p:has(>.etc-drawer-right), .tc-page-container-inner>p:has(>.etc-drawer-left) {
    position: fixed;
    z-index: 750;
    top: 0;
    margin: 0;
    pointer-events: none;
    transition: transform {{$:/config/AnimationDuration}}ms ease-in-out;
}

.tc-page-container-inner>p:has(>.etc-drawer-right.etc-drawer-open), .tc-page-container-inner>p:has(>.etc-drawer-left.etc-drawer-open){
    transform: translate(0px);
}

.etc-drawer-right, .etc-drawer-left {
    .tc-sidebar-header { padding: 0; }
    .tc-sidebar-scrollable {
        position: unset;
        margin: unset;
        padding: unset;
    }   

    margin: 0;
    .tc-tab-set { 
        .tc-tab-buttons:not(.tc-tab-set .tc-tab-set .tc-tab-buttons)  {
            align-content: center;

            button {
                pointer-events: auto;
                writing-mode: sideways-lr;
                width: 1.3rem;
                min-height: 4rem;
                max-height: 10rem;
                text-align: center;
                white-space: nowrap;
                overflow: hidden;
                text-overflow: ellipsis;
                padding-block: 0px;
                padding-inline: 4px;
                border: 1px solid <<colour sidebar-tab-border>>;
                background-color: <<colour sidebar-tab-background>>;
                svg {
                    fill: <<colour sidebar-tab-foreground>>;
                    vertical-align: text-top;
                    transform: rotate(270deg);
                }
            }

            button.tc-tab-selected {
                border: 1px solid <<colour sidebar-tab-border-selected>>;
                background-color: <<colour sidebar-tab-background-selected>>;
                svg {
                    fill: <<colour sidebar-tab-foreground-selected>>;
                }
            }
        }

        .tc-tab-content:not(.tc-tab-set .tc-tab-set .tc-tab-content)  {
            position: relative;
            pointer-events: auto;
            margin: 0;
            height: 100dvh;
            overflow: auto;
            scrollbar-gutter: stable;
            background-color: <<colour page-background>>;
            padding-inline: 14px;
        }
    }
}

/* LEFT DRAWER */

.tc-page-container-inner>p:has(>.etc-drawer-left) {
    left: 0;
    transform: translate(calc(0px - min({{$:/plugins/euth/drawers/config/leftWidth}}, calc(100vw - 2.6rem))));
}

.etc-drawer-left {
    .tc-tab-set:not(.tc-tab-set .tc-tab-set) { 
        flex-direction: row-reverse;
        .tc-tab-buttons:not(.tc-tab-set .tc-tab-set .tc-tab-buttons)  {
            transform: translate(-1px);

            button {
                border-block-start: 1px solid <<colour sidebar-tab-border-selected>>;
                box-shadow: 2px 1px 5px -3px rgba(0, 0, 0, 0.3);
                border-radius: 0 2px 2px 0;
            }

            button.tc-tab-selected {
                border-block-start: 1px solid <<colour sidebar-tab-background-selected>>;
                svg {
                    fill: <<colour sidebar-tab-foreground-selected>>;
                }
            }
        }

        .tc-tab-content:not(.tc-tab-set .tc-tab-set .tc-tab-content)  {
            width: min({{$:/plugins/euth/drawers/config/leftWidth}}, calc(100vw - 2.6rem));
            border-inline-end: 1px solid <<colour sidebar-tab-border-selected>>;
            box-shadow: -1px 1px 5px rgba(0, 0, 0, 0.3);
            direction: rtl;
            > * {direction: ltr;}
        }
    }
}

/* RIGHT DRAWER */

.tc-page-container-inner>p:has(>.etc-drawer-right) {
    right: 0;
    transform: translate(min({{$:/plugins/euth/drawers/config/rightWidth}}, calc(100vw - 2.6rem)));
}

.etc-drawer-right {
    .tc-tab-set { 
        .tc-tab-buttons:not(.tc-tab-set .tc-tab-set .tc-tab-buttons)  {
            transform: translate(1px);

            button {
                border-block-end: 1px solid <<colour sidebar-tab-border-selected>>;
                box-shadow: -2px 1px 5px -3px rgba(0, 0, 0, 0.3);
                border-radius: 2px 0 0 2px;
            }

            button.tc-tab-selected {
                border-block-end: 1px solid <<colour sidebar-tab-background-selected>>;
                svg {
                    fill: <<colour sidebar-tab-foreground-selected>>;
                }
            }
        }

        .tc-tab-content:not(.tc-tab-set .tc-tab-set .tc-tab-content)  {
            width: min({{$:/plugins/euth/drawers/config/rightWidth}}, calc(100vw - 2.6rem));
            border-inline-start: 1px solid <<colour sidebar-tab-border-selected>>;
            box-shadow: 1px 1px 5px rgba(0, 0, 0, 0.3);
        }
    }
}

/* BACKDROP */

.etc-backdrop {
    position:fixed;
    z-index:650;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    transition:
        background-color {{$:/config/AnimationDuration}}ms ease-in,
        backdrop-filter {{$:/config/AnimationDuration}}ms ease-in,
        display {{$:/config/AnimationDuration}}ms ease-in allow-discrete;
}

.etc-backdrop.etc-backdrop-open {
    background-color: #0005;
    backdrop-filter: blur(2px);
}

@starting-style {
  .etc-backdrop.etc-backdrop-open {
    background-color: #0000;
    backdrop-filter: blur(0px);
  }
}

.etc-backdrop.etc-backdrop-closed {
    background-color: #0000;
    backdrop-filter: blur(0px);
    display: none;
}

/* NON-PRINTABLE DRAWERS */

@media print {
    .etc-drawer-right, .etc-drawer-left {
        display: none;
    }
}

/* MENUBAR FIX */

<$list filter="[[$:/plugins/tiddlywiki/menubar]!is[missing]]">
    .etc-drawer-right, .etc-drawer-left {
        .tc-tab-set {
            .tc-tab-content:not(.tc-tab-set .tc-tab-set .tc-tab-content)  {
                padding-top: 32px;
            }        
        }
